  if(method==="GET"&&path.startsWith("/social/journeys/")&&path.endsWith("/card.svg")){const id=decodeURIComponent(path.slice("/social/journeys/".length,-"/card.svg".length)),format=z.enum(["square","story"]).catch("square").parse(url.searchParams.get("format")||"square"),j=await journeyDetail(db,userId,id);return new Response(journeySvg(j,format),{headers:{"Content-Type":"image/svg+xml; charset=utf-8","Cache-Control":"private, max-age=60","Content-Security-Policy":"default-src 'none'; style-src 'unsafe-inline'; img-src data:"}});}
  if(method==="GET"&&path.startsWith("/social/journeys/")){return json(await journeyDetail(db,userId,decodeURIComponent(path.slice("/social/journeys/".length))));}
  if(method==="GET"&&path.startsWith("/social/reader/")){const uidv=requireIdentity(userId);return json(await readerSnapshot(db,uidv,decodeURIComponent(path.slice("/social/reader/".length)),url));}
  if(method==="GET"&&path==="/social/feed"){const uidv=requireIdentity(userId),limit=Math.max(1,Math.min(100,Number(url.searchParams.get("limit")||40))),before=url.searchParams.get("before"),rows=(before?(await db.prepare(`SELECT e.* FROM social_events e WHERE e.moderation_status='visible' AND e.created_at<? AND (e.user_id=? OR e.user_id IN (SELECT followed_user_id FROM social_follows WHERE follower_user_id=?)) ORDER BY e.created_at DESC LIMIT ?`).bind(before,uidv,uidv,limit*3).all<any>()):(await db.prepare(`SELECT e.* FROM social_events e WHERE e.moderation_status='visible' AND (e.user_id=? OR e.user_id IN (SELECT followed_user_id FROM social_follows WHERE follower_user_id=?)) ORDER BY e.created_at DESC LIMIT ?`).bind(uidv,uidv,limit*3).all<any>())).results,out=[];for(const e of rows){if(await canSee(db,uidv,String(e.user_id),String(e.visibility))){out.push({...e,payload:asJson(e.payload_json,{}),user:await person(db,String(e.user_id)),book:e.product_id?await productSnapshot(db,String(e.product_id)):null});if(out.length>=limit)break;}}return json({items:out,nextCursor:out.length===limit?String(out.at(-1)?.created_at||""):null});}
